// Shared type definitions exactly as specified

// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Event Bus Contract
// ============================================================

export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
}

import { IEventBus } from "./types";

type Callback = (payload: unknown) => void;

export class EventBus implements IEventBus {
  private handlers: Map<string, Callback[]> = new Map();

  publish(event: string, payload: unknown): void {
    const h = this.handlers.get(event) || [];
    // call synchronously
    for (const cb of h) {
      try {
        cb(payload);
      } catch (err) {
        // swallow errors to not affect publisher
        // console.error("Event handler error", err);
      }
    }
  }

  subscribe(event: string, callback: Callback): void {
    const arr = this.handlers.get(event) || [];
    arr.push(callback);
    this.handlers.set(event, arr);
  }
}

import { IUserService, User } from "../types";
import { randomUUID } from "crypto";

export class UserService implements IUserService {
  // exclusive private store
  private store: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const id = randomUUID();
    const user: User = { id, name: input.name, email: input.email };
    this.store.set(id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.store.get(id);
    if (!user) throw new Error("User not found");
    return user;
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const user = this.getById(id);
    const updated: User = { ...user, ...input };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error("User not found");
    this.store.delete(id);
  }
}

import { IProjectService, Project } from "../types";
import { randomUUID } from "crypto";

export class ProjectService implements IProjectService {
  private store: Map<string, Project> = new Map();

  create(input: { name: string; description: string }): Project {
    const id = randomUUID();
    const project: Project = { id, name: input.name, description: input.description, memberIds: [] };
    this.store.set(id, project);
    return project;
  }

  getById(id: string): Project {
    const p = this.store.get(id);
    if (!p) throw new Error("Project not found");
    return p;
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: Partial<{ name: string; description: string }>): Project {
    const p = this.getById(id);
    const updated: Project = { ...p, ...input } as Project;
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error("Project not found");
    this.store.delete(id);
  }

  addMember(projectId: string, userId: string): Project {
    const p = this.getById(projectId);
    if (!p.memberIds.includes(userId)) {
      p.memberIds.push(userId);
      this.store.set(projectId, p);
    }
    return p;
  }

  removeMember(projectId: string, userId: string): Project {
    const p = this.getById(projectId);
    p.memberIds = p.memberIds.filter((id) => id !== userId);
    this.store.set(projectId, p);
    return p;
  }
}

import { ITaskService, Task, TaskStatus, TaskAssignedPayload, TaskStatusChangedPayload } from "../types";
import { randomUUID } from "crypto";
import { IEventBus } from "../types";

export class TaskService implements ITaskService {
  private store: Map<string, Task> = new Map();
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.eventBus = eventBus;
  }

  create(input: { title: string; description: string; projectId: string }): Task {
    const id = randomUUID();
    const task: Task = { id, title: input.title, description: input.description, status: "todo", assigneeId: null, projectId: input.projectId };
    this.store.set(id, task);
    return task;
  }

  getById(id: string): Task {
    const t = this.store.get(id);
    if (!t) throw new Error("Task not found");
    return t;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter((t) => t.projectId === projectId);
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const t = this.getById(id);
    const updated: Task = { ...t, ...input } as Task;
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error("Task not found");
    this.store.delete(id);
  }

  assign(taskId: string, assigneeId: string): Task {
    const t = this.getById(taskId);
    t.assigneeId = assigneeId;
    this.store.set(taskId, t);
    const payload: TaskAssignedPayload = { taskId: t.id, taskTitle: t.title, assigneeId };
    this.eventBus.publish("task.assigned", payload);
    return t;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const t = this.getById(taskId);
    const order: TaskStatus[] = ["todo", "in-progress", "done"];
    const oldIndex = order.indexOf(t.status);
    const newIndex = order.indexOf(newStatus);
    if (newIndex === -1) throw new Error("Invalid status");
    if (newIndex === oldIndex) return t; // no change
    if (newIndex === oldIndex + 1) {
      // forward by one - allowed
      const oldStatus = t.status;
      t.status = newStatus;
      this.store.set(taskId, t);
      const payload: TaskStatusChangedPayload = { taskId: t.id, taskTitle: t.title, assigneeId: t.assigneeId, oldStatus, newStatus };
      this.eventBus.publish("task.statusChanged", payload);
      return t;
    }
    // any other transition is invalid
    throw new Error("Invalid status transition");
  }
}

import { ICommentService, Comment, CommentAddedPayload } from "../types";
import { randomUUID } from "crypto";
import { IEventBus } from "../types";

export class CommentService implements ICommentService {
  private store: Map<string, Comment> = new Map();
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.eventBus = eventBus;
  }

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const comment: Comment = { id, taskId: input.taskId, authorId: input.authorId, body: input.body, createdAt };
    this.store.set(id, comment);
    const payload: CommentAddedPayload = { commentId: id, taskId: input.taskId, taskTitle: "", authorId: input.authorId, authorName: "" };
    // Note: taskTitle/authorName can be enriched by subscribers if needed
    this.eventBus.publish("comment.added", payload);
    return comment;
  }

  getById(id: string): Comment {
    const c = this.store.get(id);
    if (!c) throw new Error("Comment not found");
    return c;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter((c) => c.taskId === taskId);
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error("Comment not found");
    this.store.delete(id);
  }
}

import { INotificationService, Notification, TaskAssignedPayload, TaskStatusChangedPayload, CommentAddedPayload } from "../types";
import { randomUUID } from "crypto";
import { IEventBus } from "../types";

export class NotificationService implements INotificationService {
  private store: Map<string, Notification> = new Map();
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe("task.assigned", (payload) => this.onTaskAssigned(payload));
    this.eventBus.subscribe("task.statusChanged", (payload) => this.onTaskStatusChanged(payload));
    this.eventBus.subscribe("comment.added", (payload) => this.onCommentAdded(payload));
  }

  private onTaskAssigned(payload: unknown) {
    const p = payload as TaskAssignedPayload;
    const message = `Task '${p.taskTitle}' assigned to you`;
    const n: Notification = { id: randomUUID(), userId: p.assigneeId, message, read: false, createdAt: new Date().toISOString() };
    this.store.set(n.id, n);
  }

  private onTaskStatusChanged(payload: unknown) {
    const p = payload as TaskStatusChangedPayload;
    if (!p.assigneeId) return;
    const message = `Task '${p.taskTitle}' status changed to ${p.newStatus}`;
    const n: Notification = { id: randomUUID(), userId: p.assigneeId, message, read: false, createdAt: new Date().toISOString() };
    this.store.set(n.id, n);
  }

  private onCommentAdded(payload: unknown) {
    const p = payload as CommentAddedPayload;
    // CommentAddedPayload does not include assignee; responsibility of router/main to publish enriched payload if needed
    // We'll treat authorName/taskTitle maybe empty; subscribers expect task assignee id in another service. For now, can't resolve — so no-op unless payload has authorName and taskTitle and target userId encoded. But spec requires: creates notification for task assignee about new comment
    // To satisfy spec, expect payload to include authorName and taskTitle and also include a field 'assigneeId' optionally. We'll check any extra fields.
    const anyP = p as any;
    if (anyP.assigneeId) {
      const message = `New comment on '${p.taskTitle}' by ${p.authorName}`;
      const n: Notification = { id: randomUUID(), userId: anyP.assigneeId, message, read: false, createdAt: new Date().toISOString() };
      this.store.set(n.id, n);
    }
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter((n) => n.userId === userId).sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  }

  markAsRead(notificationId: string): Notification {
    const n = this.store.get(notificationId);
    if (!n) throw new Error("Notification not found");
    n.read = true;
    this.store.set(notificationId, n);
    return n;
  }
}

import http from "http";
import { parse as parseUrl } from "url";
import { EventBus } from "./event-bus";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { IEventBus } from "./types";

export class Router {
  private server: http.Server;
  private eventBus: IEventBus;
  private userService: UserService;
  private projectService: ProjectService;
  private taskService: TaskService;
  private commentService: CommentService;
  private notificationService: NotificationService;

  constructor() {
    this.eventBus = new EventBus();
    this.userService = new UserService();
    this.projectService = new ProjectService();
    this.taskService = new TaskService(this.eventBus);
    this.commentService = new CommentService(this.eventBus);
    this.notificationService = new NotificationService(this.eventBus);

    this.server = http.createServer((req, res) => this.handle(req, res));
  }

  listen(port: number) {
    return new Promise<void>((resolve) => {
      this.server.listen(port, () => resolve());
    });
  }

  close() {
    this.server.close();
  }

  private async handle(req: http.IncomingMessage, res: http.ServerResponse) {
    try {
      const method = req.method || "GET";
      const parsed = parseUrl(req.url || "", true);
      const pathname = parsed.pathname || "/";
      const query = parsed.query;

      const body = await this.readBody(req);

      // Routing
      // Users
      if (method === "GET" && pathname === "/users") return this.ok(res, this.userService.getAll());
      if (method === "POST" && pathname === "/users") return this.ok(res, this.userService.create(body));
      if (pathname.startsWith("/users/")) {
        const id = pathname.split("/")[2];
        if (method === "GET") return this.ok(res, this.userService.getById(id));
        if (method === "PUT") return this.ok(res, this.userService.update(id, body));
        if (method === "DELETE") return this.noContent(res, () => this.userService.delete(id));
      }

      // Projects
      if (method === "GET" && pathname === "/projects") return this.ok(res, this.projectService.getAll());
      if (method === "POST" && pathname === "/projects") return this.ok(res, this.projectService.create(body));
      if (pathname.startsWith("/projects/")) {
        const parts = pathname.split("/");
        const id = parts[2];
        if (parts.length === 3) {
          if (method === "GET") return this.ok(res, this.projectService.getById(id));
          if (method === "PUT") return this.ok(res, this.projectService.update(id, body));
          if (method === "DELETE") return this.noContent(res, () => this.projectService.delete(id));
        }
        if (parts.length === 4 && parts[3] === "members") {
          if (method === "POST") return this.ok(res, this.projectService.addMember(id, body.userId));
          if (method === "DELETE") return this.ok(res, this.projectService.removeMember(id, body.userId));
        }
      }

      // Tasks
      if (method === "GET" && pathname === "/tasks" && query.projectId) return this.ok(res, this.taskService.getByProject(String(query.projectId)));
      if (method === "POST" && pathname === "/tasks") return this.ok(res, this.taskService.create(body));
      if (pathname.startsWith("/tasks/")) {
        const parts = pathname.split("/");
        const id = parts[2];
        if (parts.length === 3) {
          if (method === "GET") return this.ok(res, this.taskService.getById(id));
          if (method === "PUT") return this.ok(res, this.taskService.update(id, body));
          if (method === "DELETE") return this.noContent(res, () => this.taskService.delete(id));
        }
        if (parts.length === 4 && parts[3] === "status" && method === "PUT") return this.ok(res, this.taskService.changeStatus(id, body.status));
        if (parts.length === 4 && parts[3] === "assign" && method === "PUT") return this.ok(res, this.taskService.assign(id, body.assigneeId));
      }

      // Comments
      if (method === "GET" && pathname === "/comments" && query.taskId) return this.ok(res, this.commentService.getByTask(String(query.taskId)));
      if (method === "POST" && pathname === "/comments") {
        const comment = this.commentService.create(body);
        // Enrich comment.added event with taskTitle and authorName and assigneeId if possible by reading task and user services
        // Need to access task and user stores via services here
        // We'll manually publish an enriched event
        const task = (() => {
          try { return this.taskService.getById(comment.taskId); } catch { return null; }
        })();
        const author = (() => {
          try { return this.userService.getById(comment.authorId); } catch { return null; }
        })();
        const enriched: any = { commentId: comment.id, taskId: comment.taskId, taskTitle: task?.title || "", authorId: comment.authorId, authorName: author?.name || "" };
        if (task?.assigneeId) enriched.assigneeId = task.assigneeId;
        this.eventBus.publish("comment.added", enriched);
        return this.ok(res, comment);
      }
      if (pathname.startsWith("/comments/")) {
        const id = pathname.split("/")[2];
        if (method === "GET") return this.ok(res, this.commentService.getById(id));
        if (method === "DELETE") return this.noContent(res, () => this.commentService.delete(id));
      }

      // Notifications
      if (method === "GET" && pathname === "/notifications" && query.userId) return this.ok(res, this.notificationService.getByUser(String(query.userId)));
      if (pathname.startsWith("/notifications/")) {
        const parts = pathname.split("/");
        const id = parts[2];
        if (parts.length === 4 && parts[3] === "read" && method === "PUT") return this.ok(res, this.notificationService.markAsRead(id));
      }

      this.notFound(res);
    } catch (err: any) {
      this.error(res, err);
    }
  }

  private readBody(req: http.IncomingMessage): Promise<any> {
    return new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];
      req.on("data", (c) => chunks.push(Buffer.from(c)));
      req.on("end", () => {
        if (chunks.length === 0) return resolve({});
        try {
          const s = Buffer.concat(chunks).toString();
          const obj = JSON.parse(s);
          resolve(obj);
        } catch (e) {
          reject(e);
        }
      });
      req.on("error", (e) => reject(e));
    });
  }

  private ok(res: http.ServerResponse, data: unknown) {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify(data));
  }

  private noContent(res: http.ServerResponse, fn: () => void) {
    fn();
    res.writeHead(204);
    res.end();
  }

  private notFound(res: http.ServerResponse) {
    res.writeHead(404, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Not found" }));
  }

  private error(res: http.ServerResponse, err: any) {
    res.writeHead(400, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: err?.message || String(err) }));
  }
}

import { Router } from "./router";

const router = new Router();
const PORT = 4000;

async function start() {
  await router.listen(PORT);
  console.log(`Server listening on http://localhost:${PORT}`);
}

start();

// graceful shutdown
process.on("SIGINT", () => {
  router.close();
  process.exit(0);
});

import http from "http";
import { Router } from "./router";

async function request(method: string, path: string, body?: any) {
  const opts = { hostname: "localhost", port: 4000, path, method, headers: { "Content-Type": "application/json" } } as any;
  return new Promise<any>((resolve, reject) => {
    const req = http.request(opts, (res) => {
      const chunks: Buffer[] = [];
      res.on("data", (c) => chunks.push(Buffer.from(c)));
      res.on("end", () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          if (chunks.length === 0) return resolve(null);
          try { resolve(JSON.parse(Buffer.concat(chunks).toString())); } catch (e) { resolve(null); }
        } else {
          try { resolve(JSON.parse(Buffer.concat(chunks).toString())); } catch { resolve({ status: res.statusCode }); }
        }
      });
    });
    req.on("error", reject);
    if (body) req.write(JSON.stringify(body));
    req.end();
  });
}

async function demo() {
  const router = new Router();
  await router.listen(4000);
  console.log("Demo server started on 4000");

  // create users
  const alice = await request("POST", "/users", { name: "Alice", email: "alice@example.com" });
  const bob = await request("POST", "/users", { name: "Bob", email: "bob@example.com" });
  console.log("Created users", alice, bob);

  // create project
  const project = await request("POST", "/projects", { name: "Project X", description: "Top secret" });
  console.log("Created project", project);

  // add members
  await request("POST", `/projects/${project.id}/members`, { userId: alice.id });
  await request("POST", `/projects/${project.id}/members`, { userId: bob.id });
  console.log("Added members to project");

  // create task
  const task = await request("POST", "/tasks", { title: "Task 1", description: "Do something", projectId: project.id });
  console.log("Created task", task);

  // assign to Bob
  await request("PUT", `/tasks/${task.id}/assign`, { assigneeId: bob.id });
  console.log("Assigned task to Bob");

  // change status todo -> in-progress
  await request("PUT", `/tasks/${task.id}/status`, { status: "in-progress" });
  console.log("Changed status to in-progress");

  // add comment by Alice
  await request("POST", `/comments`, { taskId: task.id, authorId: alice.id, body: "Please take a look" });
  console.log("Alice commented");

  // fetch Bob's notifications
  const notes = await request("GET", `/notifications?userId=${bob.id}`);
  console.log("Bob's notifications", notes);

  // mark first as read
  if (notes && notes.length > 0) {
    await request("PUT", `/notifications/${notes[0].id}/read`);
    console.log("Marked first notification as read");
  }

  // shutdown
  router.close();
}

if (require.main === module) {
  demo().catch((e) => console.error(e));
}
